#!/bin/sh
# Records the Linux fixtures: osquery 5.12.1 on Ubuntu 24.04 running the pack
# generated by "meiscope-collector adapter pack". Needs Docker and Go.
# Usage: sh testdata/adapters/osquery/record-linux.sh   (from the repository root)
set -e
here=testdata/adapters/osquery
work="$(mktemp -d)"
go build -o "$work/collector" ./cmd/meiscope-collector
"$work/collector" adapter pack > "$work/meiscope.conf"
for q in meiscope_certificates_posix meiscope_keystores_posix meiscope_keystore_counts_posix; do
  "$work/collector" adapter pack --query "$q" > "$work/$q.sql"
done
cp "$here/record-inner.sh" "$work/record-inner.sh"
docker build -q -t meiscope-osquery-test:5.12.1 -f "$here/Dockerfile.osquery" "$here"
mkdir -p "$work/out"
mount="$work"
if command -v cygpath >/dev/null 2>&1; then mount="$(cygpath -w "$work")"; fi
MSYS_NO_PATHCONV=1 docker run --rm --hostname app01.example.test \
  -v "$mount:/pack:ro" -v "$mount/out:/out" \
  meiscope-osquery-test:5.12.1 sh /pack/record-inner.sh
rm -rf "$here/logsink" "$here/direct"
mkdir -p "$here/logsink" "$here/direct"
cp "$work/out/log/osqueryd.snapshots.log" "$here/logsink/"
cp "$work/out"/direct-*.json "$here/direct/"
echo "recorded into $here"
